CREATE TABLE roles (id_rol BIGSERIAL PRIMARY KEY, nombre_rol VARCHAR(50) NOT NULL UNIQUE, descripcion VARCHAR(200));
CREATE TABLE usuarios (documento_usuario VARCHAR(30) PRIMARY KEY, id_rol BIGINT NOT NULL REFERENCES roles(id_rol), tipo_documento VARCHAR(10) NOT NULL, nombres VARCHAR(100) NOT NULL, apellidos VARCHAR(100) NOT NULL, correo VARCHAR(150) NOT NULL UNIQUE, contrasena_hash TEXT NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'activo');
CREATE TABLE contratos (id_contrato BIGSERIAL PRIMARY KEY, documento_contratista VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), numero_contrato VARCHAR(50) NOT NULL, anio SMALLINT NOT NULL, fecha_inicio DATE, fecha_fin DATE, objeto_contractual TEXT, documento_supervisor VARCHAR(30) REFERENCES usuarios(documento_usuario), UNIQUE(numero_contrato, anio));
CREATE TABLE obligaciones (id_obligacion BIGSERIAL PRIMARY KEY, id_contrato BIGINT NOT NULL REFERENCES contratos(id_contrato) ON DELETE CASCADE, descripcion TEXT NOT NULL);
CREATE TABLE destinos (id_destino BIGSERIAL PRIMARY KEY, ciudad VARCHAR(100) NOT NULL, departamento VARCHAR(100), entidad_destino VARCHAR(180), direccion VARCHAR(200), contacto_nombre VARCHAR(150), contacto_telefono VARCHAR(40));
CREATE TABLE estados_agenda (id_estado_agenda BIGSERIAL PRIMARY KEY, nombre_estado VARCHAR(50) NOT NULL UNIQUE, es_final BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE agendas (id_agenda BIGSERIAL PRIMARY KEY, documento_comisionado VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), id_estado_agenda BIGINT NOT NULL REFERENCES estados_agenda(id_estado_agenda), id_contrato BIGINT REFERENCES contratos(id_contrato), tipo_agenda VARCHAR(20) NOT NULL CHECK(tipo_agenda IN ('funcionario','contratista')), fecha_elaboracion DATE NOT NULL DEFAULT CURRENT_DATE, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, objeto_comision TEXT, objetivo_desplazamiento TEXT, observaciones TEXT, fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(fecha_fin >= fecha_inicio), CHECK(tipo_agenda='funcionario' OR id_contrato IS NOT NULL));
CREATE TABLE agenda_destinos (id_agenda_destino BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, id_destino BIGINT NOT NULL REFERENCES destinos(id_destino), orden SMALLINT NOT NULL, tipo_trayecto VARCHAR(20) NOT NULL CHECK(tipo_trayecto IN ('ida','regreso','interno')));
CREATE TABLE agenda_obligaciones (id_agenda_obligacion BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, id_obligacion BIGINT NOT NULL REFERENCES obligaciones(id_obligacion), UNIQUE(id_agenda,id_obligacion));
CREATE TABLE medios_transporte (id_medio_transporte BIGSERIAL PRIMARY KEY, nombre_medio VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE dias_agenda (id_dia_agenda BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, fecha DATE NOT NULL, observaciones TEXT, UNIQUE(id_agenda,fecha));
CREATE TABLE actividades (id_actividad BIGSERIAL PRIMARY KEY, id_dia_agenda BIGINT NOT NULL REFERENCES dias_agenda(id_dia_agenda) ON DELETE CASCADE, hora_inicio TIME, hora_fin TIME, descripcion TEXT NOT NULL, desplazamiento_interno BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE trayectos (id_trayecto BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, id_medio_transporte BIGINT NOT NULL REFERENCES medios_transporte(id_medio_transporte), origen_id_destino BIGINT REFERENCES destinos(id_destino), destino_id_destino BIGINT REFERENCES destinos(id_destino), tipo_trayecto VARCHAR(20) NOT NULL CHECK(tipo_trayecto IN ('ida','regreso','interno')), fecha_hora TIMESTAMP);
CREATE TABLE historial_agenda (id_historial BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, documento_usuario VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), estado_anterior VARCHAR(50), estado_nuevo VARCHAR(50) NOT NULL, fecha_evento TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, comentario TEXT);
CREATE TABLE revisiones_agenda (id_revision BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, documento_revisor VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), decision VARCHAR(20) NOT NULL CHECK(decision IN ('aprobada','devuelta','rechazada')), observacion TEXT, fecha_revision TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE firmas_documentos (id_firma_documento BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL REFERENCES agendas(id_agenda) ON DELETE CASCADE, documento_usuario VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), tipo_firma VARCHAR(30) NOT NULL, archivo_firma_url TEXT, fecha_firma TIMESTAMP);
CREATE TABLE legalizaciones (id_legalizacion BIGSERIAL PRIMARY KEY, id_agenda BIGINT NOT NULL UNIQUE REFERENCES agendas(id_agenda), documento_responsable VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), estado_legalizacion VARCHAR(30) NOT NULL DEFAULT 'borrador', fecha_presentacion DATE, fecha_cierre DATE, observaciones TEXT);
CREATE TABLE tipos_gasto (id_tipo_gasto BIGSERIAL PRIMARY KEY, nombre_tipo_gasto VARCHAR(60) NOT NULL UNIQUE, requiere_soporte BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE gastos_legalizacion (id_gasto BIGSERIAL PRIMARY KEY, id_legalizacion BIGINT NOT NULL REFERENCES legalizaciones(id_legalizacion) ON DELETE CASCADE, id_tipo_gasto BIGINT NOT NULL REFERENCES tipos_gasto(id_tipo_gasto), fecha_gasto DATE, descripcion TEXT, valor NUMERIC(12,2) NOT NULL CHECK(valor>=0), numero_documento VARCHAR(80));
CREATE TABLE soportes_legalizacion (id_soporte BIGSERIAL PRIMARY KEY, id_gasto BIGINT NOT NULL REFERENCES gastos_legalizacion(id_gasto) ON DELETE CASCADE, nombre_archivo VARCHAR(255) NOT NULL, ruta_archivo TEXT NOT NULL, fecha_carga TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE revisiones_legalizacion (id_revision_legalizacion BIGSERIAL PRIMARY KEY, id_legalizacion BIGINT NOT NULL REFERENCES legalizaciones(id_legalizacion) ON DELETE CASCADE, documento_revisor VARCHAR(30) NOT NULL REFERENCES usuarios(documento_usuario), decision VARCHAR(20) NOT NULL CHECK(decision IN ('aprobada','devuelta','rechazada')), observacion TEXT, fecha_revision TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO estados_agenda(nombre_estado,es_final) VALUES ('Borrador',FALSE),('Enviada a supervisor',FALSE),('En revisión de viáticos',FALSE),('En firma del subdirector',FALSE),('Aprobada',TRUE),('Devuelta',FALSE),('Anulada',TRUE);
